const fs = require('fs');
const zlib = require('zlib');
const path = '/workspace/testbed/docs/customer_report.docx';
const buf = fs.readFileSync(path);

// Check first bytes
console.log('First 4 bytes:', buf.slice(0,4).toString('hex'));

if (buf[0] === 0x50 && buf[1] === 0x4B) {
  // It's a ZIP - manually parse to find word/document.xml
  // Use built-in unzip approach
  const { execSync } = require('child_process');
  try {
    const result = execSync('unzip -p \"' + path + '\" word/document.xml 2>/dev/null');
    // Strip XML tags and extract text
    const xml = result.toString();
    const texts = xml.match(/<w:t[^>]*?>([^<]*)<\/w:t>/g) || [];
    const content = texts.map(t => t.replace(/<[^>]*>/g, '')).join(' ');
    console.log(content);
  } catch(e) {
    console.log('unzip failed:', e.message);
  }
} else {
  console.log('Not a zip file. Raw content preview:');
  console.log(buf.toString('utf8', 0, 2000));
}
