const fs = require('fs');
const path = '/workspace/testbed/docs/customer_report.docx';
const buf = fs.readFileSync(path);

// Manual ZIP parsing to list filenames
let offset = 0;
const files = [];
while (offset < buf.length - 4) {
  const sig = buf.readUInt32LE(offset);
  if (sig !== 0x04034b50) break; // local file header
  const fnLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const compSize = buf.readUInt32LE(offset + 18);
  const method = buf.readUInt16LE(offset + 8);
  const fname = buf.toString('utf8', offset + 30, offset + 30 + fnLen);
  const dataStart = offset + 30 + fnLen + extraLen;
  files.push({ fname, method, compSize, dataStart });
  offset = dataStart + compSize;
}
console.log('Files in zip:', files.map(f => f.fname + ' (method:' + f.method + ', size:' + f.compSize + ')'));

// Find word/document.xml
const docEntry = files.find(f => f.fname === 'word/document.xml');
if (docEntry) {
  let xmlBuf;
  if (docEntry.method === 0) {
    xmlBuf = buf.slice(docEntry.dataStart, docEntry.dataStart + docEntry.compSize);
  } else if (docEntry.method === 8) {
    const zlib = require('zlib');
    const compressed = buf.slice(docEntry.dataStart, docEntry.dataStart + docEntry.compSize);
    xmlBuf = zlib.inflateRawSync(compressed);
  }
  if (xmlBuf) {
    const xml = xmlBuf.toString('utf8');
    // Extract paragraphs - split by paragraph markers
    const paragraphs = xml.split(/<\/w:p>/);
    const lines = paragraphs.map(p => {
      const texts = p.match(/<w:t[^>]*?>([^<]*)<\/w:t>/g) || [];
      return texts.map(t => t.replace(/<[^>]*>/g, '')).join('');
    }).filter(l => l.length > 0);
    console.log('\\n--- Document Content ---\\n');
    lines.forEach(l => console.log(l));
  }
}
"
